const deviceIconURL = name => {
    const svg = ICONS[name];
    if (!svg) throw new Error(`Unknown device icon: ${name}`);
    return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
};

export {deviceIconURL, ICONS as deviceIcons};
